#ifndef O_ACCMODE
#define O_ACCMODE (O_RDONLY | O_WRONLY | O_RDWR)
#endif

#define SYS_FILE_FD_BASE 3
#define SYS_FILE_FD_MAX  8

typedef struct
{
  lfs_t *fs;
  lfs_file_t file;
  int in_use;
} sys_file_fd_t;

static sys_file_fd_t g_file_fds[SYS_FILE_FD_MAX];

static void set_errno_from_lfs(int rc)
{
  switch (rc)
  {
  case LFS_ERR_NOENT:
    errno = ENOENT;
    break;
  case LFS_ERR_NOTDIR:
    errno = ENOTDIR;
    break;
  case LFS_ERR_EXIST:
    errno = EEXIST;
    break;
  case LFS_ERR_NOMEM:
    errno = ENOMEM;
    break;
  case LFS_ERR_IO:
    errno = EIO;
    break;
  case LFS_ERR_INVAL:
    errno = EINVAL;
    break;
  case LFS_ERR_BADF:
    errno = EBADF;
    break;
  case LFS_ERR_ISDIR:
    errno = EISDIR;
    break;
  case LFS_ERR_NAMETOOLONG:
    errno = ENAMETOOLONG;
    break;
  case LFS_ERR_FBIG:
    errno = EFBIG;
    break;
  case LFS_ERR_NOSPC:
    errno = ENOSPC;
    break;
  default:
    errno = EIO;
    break;
  }
}

static lfs_t *get_lfs_or_init(void)
{
  lfs_t *lfs = lfs_port_fs();
  int rc;

  if (lfs != NULL)
  {
    return lfs;
  }

  rc = lfs_port_init();
  if (rc < 0)
  {
    set_errno_from_lfs(rc);
    return NULL;
  }

  lfs = lfs_port_fs();
  if (lfs == NULL)
  {
    errno = EIO;
  }

  return lfs;
}

static int map_open_flags(int flags)
{
  int lfs_flags = 0;

  switch (flags & O_ACCMODE)
  {
  case O_RDONLY:
    lfs_flags |= LFS_O_RDONLY;
    break;
  case O_WRONLY:
    lfs_flags |= LFS_O_WRONLY;
    break;
  case O_RDWR:
    lfs_flags |= LFS_O_RDWR;
    break;
  default:
    errno = EINVAL;
    return -1;
  }

  if ((flags & O_CREAT) != 0)
  {
    lfs_flags |= LFS_O_CREAT;
  }
  if ((flags & O_EXCL) != 0)
  {
    lfs_flags |= LFS_O_EXCL;
  }
  if ((flags & O_TRUNC) != 0)
  {
    lfs_flags |= LFS_O_TRUNC;
  }
  if ((flags & O_APPEND) != 0)
  {
    lfs_flags |= LFS_O_APPEND;
  }

  return lfs_flags;
}

static int alloc_file_fd(void)
{
  int idx;

  for (idx = 0; idx < SYS_FILE_FD_MAX; idx++)
  {
    if (!g_file_fds[idx].in_use)
    {
      g_file_fds[idx].in_use = 1;
      g_file_fds[idx].fs = NULL;
      memset(&g_file_fds[idx].file, 0, sizeof(g_file_fds[idx].file));
      return SYS_FILE_FD_BASE + idx;
    }
  }

  errno = EMFILE;
  return -1;
}

static sys_file_fd_t *get_file_fd(int fd)
{
  int idx = fd - SYS_FILE_FD_BASE;

  if ((fd < SYS_FILE_FD_BASE) || (idx < 0) || (idx >= SYS_FILE_FD_MAX))
  {
    return NULL;
  }

  if (!g_file_fds[idx].in_use)
  {
    return NULL;
  }

  return &g_file_fds[idx];
}


