__attribute__((weak)) int _read(int file, char *ptr, int len)
{
  int DataIdx;
  sys_file_fd_t *ctx;
  lfs_ssize_t rc;

  if ((ptr == NULL) || (len < 0))
  {
    errno = EINVAL;
    return -1;
  }

  if (file < SYS_FILE_FD_BASE)
  {
    for (DataIdx = 0; DataIdx < len; DataIdx++)
    {
      *ptr++ = __io_getchar();
    }

    return len;
  }

  ctx = get_file_fd(file);
  if (ctx == NULL)
  {
    errno = EBADF;
    return -1;
  }

  if (ctx->fs == NULL)
  {
    errno = EIO;
    return -1;
  }

  rc = lfs_file_read(ctx->fs, &ctx->file, ptr, (lfs_size_t)len);
  if (rc < 0)
  {
    set_errno_from_lfs((int)rc);
    return -1;
  }

  DataIdx = (int)rc;
  return DataIdx;
}

__attribute__((weak)) int _write(int file, char *ptr, int len)
{
  int DataIdx;
  sys_file_fd_t *ctx;
  lfs_ssize_t rc;

  if ((ptr == NULL) || (len < 0))
  {
    errno = EINVAL;
    return -1;
  }

  if (file < SYS_FILE_FD_BASE)
  {
    for (DataIdx = 0; DataIdx < len; DataIdx++)
    {
      __io_putchar(*ptr++);
    }
    return len;
  }

  ctx = get_file_fd(file);
  if (ctx == NULL)
  {
    errno = EBADF;
    return -1;
  }

  if (ctx->fs == NULL)
  {
    errno = EIO;
    return -1;
  }

  rc = lfs_file_write(ctx->fs, &ctx->file, ptr, (lfs_size_t)len);
  if (rc < 0)
  {
    set_errno_from_lfs((int)rc);
    return -1;
  }

  DataIdx = (int)rc;
  return DataIdx;
}

int _close(int file)
{
  sys_file_fd_t *ctx;
  int rc;

  if (file < SYS_FILE_FD_BASE)
  {
    return 0;
  }

  ctx = get_file_fd(file);
  if (ctx == NULL)
  {
    errno = EBADF;
    return -1;
  }

  rc = lfs_file_close(ctx->fs, &ctx->file);
  ctx->in_use = 0;
  ctx->fs = NULL;
  memset(&ctx->file, 0, sizeof(ctx->file));

  if (rc < 0)
  {
    set_errno_from_lfs(rc);
    return -1;
  }

  return 0;
}


int _fstat(int file, struct stat *st)
{
  sys_file_fd_t *ctx;
  lfs_soff_t size;

  if (st == NULL)
  {
    errno = EINVAL;
    return -1;
  }

  if (file < SYS_FILE_FD_BASE)
  {
    st->st_mode = S_IFCHR;
    st->st_size = 0;
    return 0;
  }

  ctx = get_file_fd(file);
  if (ctx == NULL)
  {
    errno = EBADF;
    return -1;
  }

  size = lfs_file_size(ctx->fs, &ctx->file);
  if (size < 0)
  {
    set_errno_from_lfs((int)size);
    return -1;
  }

  st->st_mode = S_IFREG;
  st->st_size = (off_t)size;
  return 0;
}

int _isatty(int file)
{
  return (file < SYS_FILE_FD_BASE) ? 1 : 0;
}

int _lseek(int file, int ptr, int dir)
{
  sys_file_fd_t *ctx;
  lfs_soff_t rc;

  if (file < SYS_FILE_FD_BASE)
  {
    return 0;
  }

  ctx = get_file_fd(file);
  if (ctx == NULL)
  {
    errno = EBADF;
    return -1;
  }

  switch (dir)
  {
  case SEEK_SET:
    rc = lfs_file_seek(ctx->fs, &ctx->file, (lfs_soff_t)ptr, LFS_SEEK_SET);
    break;
  case SEEK_CUR:
    rc = lfs_file_seek(ctx->fs, &ctx->file, (lfs_soff_t)ptr, LFS_SEEK_CUR);
    break;
  case SEEK_END:
    rc = lfs_file_seek(ctx->fs, &ctx->file, (lfs_soff_t)ptr, LFS_SEEK_END);
    break;
  default:
    errno = EINVAL;
    return -1;
  }

  if (rc < 0)
  {
    set_errno_from_lfs((int)rc);
    return -1;
  }

  return (int)rc;
}

int _open(char *path, int flags, ...)
{
  lfs_t *lfs;
  sys_file_fd_t *ctx;
  int fd;
  int lfs_flags;

  if (path == NULL)
  {
    errno = EINVAL;
    return -1;
  }

  if ((flags & O_CREAT) != 0)
  {
    va_list ap;

    va_start(ap, flags);
    (void)va_arg(ap, int);
    va_end(ap);
  }

  lfs_flags = map_open_flags(flags);
  if (lfs_flags < 0)
  {
    return -1;
  }

  lfs = get_lfs_or_init();
  if (lfs == NULL)
  {
    return -1;
  }

  fd = alloc_file_fd();
  if (fd < 0)
  {
    return -1;
  }

  ctx = get_file_fd(fd);
  if (ctx == NULL)
  {
    errno = EBADF;
    return -1;
  }

  ctx->fs = lfs;
  {
    int rc = lfs_file_open(lfs, &ctx->file, path, lfs_flags);

    if (rc < 0)
    {
      ctx->in_use = 0;
      ctx->fs = NULL;
      memset(&ctx->file, 0, sizeof(ctx->file));
      set_errno_from_lfs(rc);
      return -1;
    }
  }

  return fd;
}

