int _stat(const char *file, struct stat *st)
{
  lfs_t *lfs;
  struct lfs_info info;
  int rc;

  if ((file == NULL) || (st == NULL))
  {
    errno = EINVAL;
    return -1;
  }

  lfs = lfs_port_fs();
  if (lfs != NULL)
  {
    rc = lfs_stat(lfs, file, &info);
    if (rc == 0)
    {
      st->st_mode = (info.type == LFS_TYPE_DIR) ? S_IFDIR : S_IFREG;
      st->st_size = (off_t)info.size;
      return 0;
    }

    switch (rc)
    {
    case LFS_ERR_NOENT:
      errno = ENOENT;
      break;
    case LFS_ERR_NOTDIR:
      errno = ENOTDIR;
      break;
    case LFS_ERR_EXIST:
      errno = EEXIST;
      break;
    case LFS_ERR_NOMEM:
      errno = ENOMEM;
      break;
    case LFS_ERR_IO:
      errno = EIO;
      break;
    case LFS_ERR_INVAL:
      errno = EINVAL;
      break;
    case LFS_ERR_BADF:
      errno = EBADF;
      break;
    case LFS_ERR_ISDIR:
      errno = EISDIR;
      break;
    case LFS_ERR_NAMETOOLONG:
      errno = ENAMETOOLONG;
      break;
    case LFS_ERR_FBIG:
      errno = EFBIG;
      break;
    case LFS_ERR_NOSPC:
      errno = ENOSPC;
      break;
    default:
      errno = EIO;
      break;
    }
    return -1;
  }

  /* Fallback before littlefs is mounted: keep console-like behavior. */
  st->st_mode = S_IFCHR;
  st->st_size = 0;
  return 0;
}

